namespace sv_cbcb8b65a4cd400daba24dd920522132.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@namespace sv_cbcb8b65a4cd400daba24dd920522132.Components.Pages.Apply
@using sv_cbcb8b65a4cd400daba24dd920522132.Models

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   StepNames="stepNames"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-banner">@errorMessage</div>
    }

    @if (currentStep == 0)
    {
        @* Step 1: Personal Info *@
        <section class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label>Full Name *</label>
                <input type="text" @bind="fullName" />
            </div>
            <div class="form-group">
                <label>Email *</label>
                <input type="email" @bind="email" />
            </div>
            <div class="form-group">
                <label>Phone *</label>
                <input type="tel" @bind="phone" />
            </div>
            <div class="form-group">
                <label>Address *</label>
                <textarea rows="2" @bind="address"></textarea>
            </div>
            <div class="step-actions">
                <button class="btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                    @(isValidating ? "Validating..." : "Next")
                </button>
            </div>
        </section>
    }
    else if (currentStep == 1)
    {
        @* Step 2: Work History *@
        <section class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var index = i;
                var entry = workEntries[index];
                <WorkEntryForm Company="@entry.Company"
                               Title="@entry.Title"
                               StartDate="@entry.StartDate"
                               EndDate="@entry.EndDate"
                               IsCurrent="@entry.IsCurrent"
                               Description="@entry.Description"
                               ShowRemove="@(workEntries.Count > 1)"
                               OnRemove="() => RemoveWorkEntry(index)"
                               OnChanged="data => UpdateWorkEntry(index, data)" />
            }
            <button type="button" class="btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-actions">
                <button class="btn-outline" @onclick="() => GoToStep(0)">Back</button>
                <button class="btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 2)
    {
        @* Step 3: References *@
        <section class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < references.Count; i++)
            {
                var index = i;
                var r = references[index];
                <ReferenceForm Name="@r.Name"
                               Relationship="@r.Relationship"
                               Email="@r.Email"
                               Phone="@r.Phone"
                               ShowRemove="@(references.Count > 2)"
                               OnRemove="() => RemoveReference(index)"
                               OnChanged="data => UpdateReference(index, data)" />
            }
            @if (references.Count < 3)
            {
                <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-actions">
                <button class="btn-outline" @onclick="() => GoToStep(1)">Back</button>
                <button class="btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 3)
    {
        @* Step 4: Cover Letter *@
        <section class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <textarea rows="12" maxlength="2000" @bind="coverLetter" @bind:event="oninput"></textarea>
                <div class="char-count">@coverLetter.Length / 2000 characters</div>
            </div>
            <div class="step-actions">
                <button class="btn-outline" @onclick="() => GoToStep(2)">Back</button>
                <button class="btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </section>
    }
    else if (currentStep == 4)
    {
        @* Step 5: Review & Submit *@
        <section class="step-content">
            @if (submittedId.HasValue)
            {
                <div class="confirmation">
                    <h2>&#10003; Application Submitted!</h2>
                    <p>Your application ID is: <strong>@submittedId.Value</strong></p>
                    <p>Thank you for applying. We'll be in touch soon.</p>
                </div>
            }
            else
            {
                <h2>Review &amp; Submit</h2>

                <div class="review-section">
                    <h3>Personal Information <button class="btn-link" @onclick="() => GoToStep(0)">Edit</button></h3>
                    <dl>
                        <dt>Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <h3>Work History <button class="btn-link" @onclick="() => GoToStep(1)">Edit</button></h3>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-entry">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>References <button class="btn-link" @onclick="() => GoToStep(2)">Edit</button></h3>
                    @foreach (var r in references)
                    {
                        <div class="review-entry">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            @r.Email @(!string.IsNullOrEmpty(r.Phone) ? $"• {r.Phone}" : "")
                        </div>
                    }
                </div>

                <div class="review-section">
                    <h3>Cover Letter <button class="btn-link" @onclick="() => GoToStep(3)">Edit</button></h3>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                <div class="step-actions">
                    <button class="btn-outline" @onclick="() => GoToStep(3)">Back</button>
                    <button class="btn-primary btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @(isSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            }
        </section>
    }
</div>

@code {
    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int currentStep;
    private HashSet<int> completedSteps = new();
    private string? errorMessage;
    private bool isValidating;
    private bool isSubmitting;
    private int? submittedId;

    // Step 1 state
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 state
    private List<WorkEntryState> workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceState> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < currentStep || completedSteps.Contains(step))
        {
            currentStep = step;
            errorMessage = null;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isValid)
            {
                errorMessage = "The email address is not valid. Please check and try again.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        completedSteps.Add(0);
        currentStep = 1;
    }

    private void NextFromWorkHistory()
    {
        errorMessage = null;
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Please fill in company name and job title for all entries.";
                return;
            }
        }

        completedSteps.Add(1);
        currentStep = 2;
    }

    private void NextFromReferences()
    {
        errorMessage = null;
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Please fill in name, relationship, and email for all references.";
                return;
            }
        }

        completedSteps.Add(2);
        currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        errorMessage = null;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    // Work entry helpers
    private void AddWorkEntry() => workEntries.Add(new());
    private void RemoveWorkEntry(int index) => workEntries.RemoveAt(index);
    private void UpdateWorkEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        workEntries[index] = new WorkEntryState
        {
            Company = data.Company, Title = data.Title, StartDate = data.StartDate,
            EndDate = data.EndDate, IsCurrent = data.IsCurrent, Description = data.Description
        };
    }

    // Reference helpers
    private void AddReference() { if (references.Count < 3) references.Add(new()); }
    private void RemoveReference(int index) => references.RemoveAt(index);
    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        references[index] = new ReferenceState
        {
            Name = data.Name, Relationship = data.Relationship, Email = data.Email, Phone = data.Phone
        };
    }

    private class WorkEntryState
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceState
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.apply-container {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step-item.active {
    border-bottom-color: #1a73e8;
    font-weight: 600;
}

.step-item.completed {
    border-bottom-color: #34a853;
}

.step-item.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    font: inherit;
    color: inherit;
    width: 100%;
    padding: 0;
}

.step-item.completed .step-button {
    cursor: pointer;
    color: #34a853;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
