{"file_text": ".apply-container {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step-item.active {
    border-bottom-color: #1a73e8;
    font-weight: 600;
}

.step-item.completed {
    border-bottom-color: #34a853;
}

.step-item.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    font: inherit;
    color: inherit;
    width: 100%;
    padding: 0;
}

.step-item.completed .step-button {
    cursor: pointer;
    color: #34a853;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: #e0e0e0;
    font-size: 0.85rem;
    font-weight: 600;
}

.step-item.active .step-icon {
    background: #1a73e8;
    color: #fff;
}

.step-item.completed .step-icon {
    background: #34a853;
    color: #fff;
}

.step-label {
    font-size: 0.8rem;
}

/* Form elements */
.step-content {
    animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font: inherit;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Cards */
.work-entry-card,
.reference-card {
    position: relative;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.btn-remove {
    position: absolute;
    top: 0.5rem;
    right: 0.75rem;
    background: none;
    border: none;
    color: #d93025;
    cursor: pointer;
    font-size: 0.85rem;
}

/* Buttons */
.step-actions {
    display: flex;
    gap: 1rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

.btn-primary {
    background: #1a73e8;
    color: #fff;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font: inherit;
    cursor: pointer;
}

.btn-primary:hover { background: #1557b0; }
.btn-primary:disabled { opacity: 0.6; cursor: not-allowed; }

.btn-outline {
    background: #fff;
    color: #1a73e8;
    border: 1px solid #1a73e8;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font: inherit;
    cursor: pointer;
}

.btn-secondary {
    background: none;
    border: 1px dashed #999;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    color: #555;
    font: inherit;
}

.btn-link {
    background: none;
    border: none;
    color: #1a73e8;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.05rem;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Error banner */
.error-banner {
    background: #fce8e6;
    color: #d93025;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

/* Review sections */
.review-section {
    border-bottom: 1px solid #e0e0e0;
    padding: 1rem 0;
}

.review-section h3 {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 0 0 0.75rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-entry {
    margin-bottom: 0.75rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f5f5f5;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h2 {
    color: #34a853;
}
