namespace sv_cbcb8b65a4cd400daba24dd920522132;

/// <summary>
/// Placeholder implementation for development. Replace with a real implementation
/// that calls your backend API or database.
/// </summary>
public class PlaceholderApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public Task<int> SubmitApplicationAsync(JobApplication application)
    {
        var id = Interlocked.Increment(ref _nextId);
        return Task.FromResult(id);
    }

    public Task<bool> ValidateEmailAsync(string email)
    {
        var isValid = !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
        return Task.FromResult(isValid);
    }
}

